import (
	"fmt"
	"time"
)

func age(birth, today time.Time) int {
	years := today.Year() - birth.Year()
	birthday := time.Date(today.Year(), birth.Month(), birth.Day(), 0, 0, 0, 0, time.UTC)
	if today.Before(birthday) {
		years--
	}
	return years
}

func main() {
	birth := time.Date(2000, time.December, 25, 0, 0, 0, 0, time.UTC)
	today := time.Date(2026, time.October, 18, 0, 0, 0, 0, time.UTC)
	fmt.Println(age(birth, today))
	fmt.Println(age(birth, time.Date(2026, time.December, 25, 0, 0, 0, 0, time.UTC)))
}

