import (
	"fmt"
	"strings"
	"time"
)

func human(d time.Duration) string {
	h := int(d / time.Hour)
	m := int(d % time.Hour / time.Minute)
	s := int(d % time.Minute / time.Second)

	var parts []string
	if h > 0 {
		parts = append(parts, fmt.Sprintf("%d soat", h))
	}
	if m > 0 {
		parts = append(parts, fmt.Sprintf("%d daqiqa", m))
	}
	if s > 0 || len(parts) == 0 {
		parts = append(parts, fmt.Sprintf("%d soniya", s))
	}
	return strings.Join(parts, " ")
}

func main() {
	fmt.Println(human(2*time.Hour + 5*time.Minute))
	fmt.Println(human(90 * time.Second))
	fmt.Println(human(45 * time.Second))
	fmt.Println(human(0))
}

