import (
	"fmt"
	"time"
)

func fetch(delay time.Duration) <-chan string {
	ch := make(chan string, 1)
	go func() {
		time.Sleep(delay)
		ch <- "javob keldi"
	}()
	return ch
}

func main() {
	for _, delay := range []time.Duration{10 * time.Millisecond, 400 * time.Millisecond} {
		select {
		case msg := <-fetch(delay):
			fmt.Println(delay, "->", msg)
		case <-time.After(150 * time.Millisecond):
			fmt.Println(delay, "-> timeout")
		}
	}
}

