)

func stats(xs []float64) (mean, std float64) {
	for _, x := range xs {
		mean += x
	}
	mean /= float64(len(xs))
	for _, x := range xs {
		std += math.Pow(x-mean, 2)
	}
	std = math.Sqrt(std / float64(len(xs)))
	return
}

func main() {
	marks := []float64{4, 8, 6, 5, 3, 7, 9, 6}
	mean, std := stats(marks)
	fmt.Printf("o'rtacha=%.2f og'ish=%.2f\n", mean, std)
}

