)

type Prize struct {
	Name   string
	Weight int
}

func draw(r *rand.Rand, prizes []Prize) string {
	total := 0
	for _, p := range prizes {
		total += p.Weight
	}
	n := r.IntN(total)
	for _, p := range prizes {
		if n < p.Weight {
			return p.Name
		}
		n -= p.Weight
	}
	return ""
}

func main() {
	r := rand.New(rand.NewPCG(1, 1))
	prizes := []Prize{{"oddiy", 70}, {"kamyob", 25}, {"afsonaviy", 5}}
	counts := map[string]int{}
	for range 1000 {
		counts[draw(r, prizes)]++
	}
	fmt.Println(counts)
}

