import (
	"context"
	"fmt"
	"os"
	"os/signal"
	"sync"
)

func main() {
	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt)
	defer stop()

	jobs := make(chan int)
	var wg sync.WaitGroup
	wg.Go(func() {
		for {
			select {
			case <-ctx.Done():
				fmt.Println("ishchi to'xtadi:", ctx.Err())
				return
			case j := <-jobs:
				fmt.Println("vazifa", j, "bajarildi")
			}
		}
	})

	for j := 1; j <= 3; j++ {
		jobs <- j
	}
	stop() // Ctrl+C o'rnida
	wg.Wait()
}

