import (
	"context"
	"fmt"
	"io"
	"log/slog"
	"os"
	"slices"
	"strings"
)

type PlainHandler struct {
	w     io.Writer
	min   slog.Level
	attrs []slog.Attr
}

func (h *PlainHandler) Enabled(_ context.Context, l slog.Level) bool { return l >= h.min }

func (h *PlainHandler) Handle(_ context.Context, r slog.Record) error {
	var sb strings.Builder
	fmt.Fprintf(&sb, "[%s] %s", r.Level, r.Message)
	for _, a := range h.attrs {
		fmt.Fprintf(&sb, " %s=%v", a.Key, a.Value)
	}
	r.Attrs(func(a slog.Attr) bool {
		fmt.Fprintf(&sb, " %s=%v", a.Key, a.Value)
		return true
	})
	sb.WriteByte('\n')
	_, err := io.WriteString(h.w, sb.String())
	return err
}

func (h *PlainHandler) WithAttrs(attrs []slog.Attr) slog.Handler {
	return &PlainHandler{w: h.w, min: h.min, attrs: append(slices.Clone(h.attrs), attrs...)}
}

func (h *PlainHandler) WithGroup(string) slog.Handler { return h } // soddalik uchun

func main() {
	logger := slog.New(&PlainHandler{w: os.Stdout, min: slog.LevelInfo})
	logger.Debug("ko'rinmaydi")
	logger.Info("salom", "user", "Aziz")
	logger.With("app", "demo").Warn("ogohlantirish", "kod", 7)
