		return nil
	}
	result := make(map[string]string)
	for i, name := range re.SubexpNames() {
		if i != 0 && name != "" {
			result[name] = m[i]
		}
	}
	return result
}

func main() {
	re := regexp.MustCompile(`(?P<user>\w+)@(?P<domain>[\w.]+)`)
	fmt.Println(namedMatches(re, "aziz@mail.uz"))
	fmt.Println(namedMatches(re, "email emas"))
}

