var logRe = regexp.MustCompile(`^(?P<ip>\d+\.\d+\.\d+\.\d+) \[(?P<time>[^\]]+)\] "(?P<method>[A-Z]+) (?P<path>\S+)" (?P<status>\d{3})$`)

type Entry struct {
	IP, Time, Method, Path string
	Status                 int
}

func parse(line string) (Entry, bool) {
	m := logRe.FindStringSubmatch(line)
	if m == nil {
		return Entry{}, false
	}
	get := func(name string) string { return m[logRe.SubexpIndex(name)] }
	status, _ := strconv.Atoi(get("status"))
	return Entry{get("ip"), get("time"), get("method"), get("path"), status}, true
}

