import (
	"fmt"
	"io"
	"os"
)

type numberedWriter struct {
	w     io.Writer
	line  int
	start bool
}

func newNumberedWriter(w io.Writer) *numberedWriter {
	return &numberedWriter{w: w, start: true}
}

func (n *numberedWriter) Write(p []byte) (int, error) {
	for _, b := range p {
		if n.start {
			n.line++
			if _, err := fmt.Fprintf(n.w, "%2d: ", n.line); err != nil {
				return 0, err
			}
			n.start = false
		}
		if _, err := n.w.Write([]byte{b}); err != nil {
			return 0, err
		}
		n.start = b == '\n'
	}
	return len(p), nil
}

func main() {
	w := newNumberedWriter(os.Stdout)
	fmt.Fprintln(w, "birinchi")
	fmt.Fprintln(w, "ikkinchi")
	fmt.Fprint(w, "uchinchi\nto'rtinchi\n")
}

