type limitedDisk struct {
	free int
	data []byte
}

func (d *limitedDisk) Write(p []byte) (int, error) {
	if len(p) > d.free {
		d.data = append(d.data, p[:d.free]...)
		n := d.free
		d.free = 0
		return n, errors.New("disk to'ldi")
	}
	d.free -= len(p)
	d.data = append(d.data, p...)
	return len(p), nil
}

func main() {
