import (
	"encoding/binary"
	"errors"
	"fmt"
)

func encode(payload string) []byte {
	frame := []byte{'G', 'O'}
	frame = binary.BigEndian.AppendUint16(frame, uint16(len(payload)))
	return append(frame, payload...)
}

func decode(frame []byte) (string, error) {
	if len(frame) < 4 || string(frame[:2]) != "GO" {
		return "", errors.New("noto'g'ri kadr")
	}
	n := int(binary.BigEndian.Uint16(frame[2:4]))
	if len(frame) < 4+n {
		return "", errors.New("kadr to'liq emas")
	}
	return string(frame[4 : 4+n]), nil
}

func main() {
	frame := encode("salom")
	fmt.Printf("% x\n", frame)
	for _, f := range [][]byte{frame, frame[:6], []byte("XX")} {
		text, err := decode(f)
		fmt.Printf("%q %v\n", text, err)
	}
}

