	h.Write([]byte(key))
	return h.Sum32() % n
}

func main() {
	for _, name := range []string{"Aziz", "Dilnoza", "Vali", "Madina", "Aziz"} {
		fmt.Printf("%-8s -> shard %d\n", name, bucket(name, 4))
	}
}

package main

import (
	"crypto/hmac"
	"crypto/sha256"
	"fmt"
)

func sign(key, msg string) []byte {
	mac := hmac.New(sha256.New, []byte(key))
	mac.Write([]byte(msg))
	return mac.Sum(nil)
}

func main() {
	sig := sign("maxfiy-kalit", "to'lov:100000")
	fmt.Printf("%.16x...\n", sig)

	fmt.Println(hmac.Equal(sig, sign("maxfiy-kalit", "to'lov:100000")))
	fmt.Println(hmac.Equal(sig, sign("maxfiy-kalit", "to'lov:900000")))
	fmt.Println(hmac.Equal(sig, sign("boshqa-kalit", "to'lov:100000")))
}

