)

func main() {
	files := []struct{ name, content string }{
		{"a.txt", "salom"},
		{"b.txt", "dunyo"},
		{"c.txt", "salom"},
		{"d.txt", "dunyo"},
		{"e.txt", "yagona"},
	}

	groups := map[[32]byte][]string{}
	for _, f := range files {
		sum := sha256.Sum256([]byte(f.content))
		groups[sum] = append(groups[sum], f.name)
	}

	for _, f := range files {
		sum := sha256.Sum256([]byte(f.content))
		if names, ok := groups[sum]; ok {
			if len(names) > 1 {
				fmt.Println("dublikat:", names)
			}
			delete(groups, sum)
		}
	}
}

package main

import (
	"encoding/json"
	"fmt"
)

type Level int

const (
	Debug Level = iota
	Info
	Warn
)

var names = []string{"debug", "info", "warn"}

func (l Level) MarshalText() ([]byte, error) { return []byte(names[l]), nil }

func (l *Level) UnmarshalText(text []byte) error {
	for i, n := range names {
		if n == string(text) {
			*l = Level(i)
			return nil
		}
	}
	return fmt.Errorf("noma'lum daraja: %q", text)
}

type Config struct {
	Level Level `json:"level"`
}

func main() {
	data, _ := json.Marshal(Config{Level: Warn})
	fmt.Println(string(data))

	var c Config
	err := json.Unmarshal([]byte(`{"level":"info"}`), &c)
	fmt.Println(c.Level, err)

	err = json.Unmarshal([]byte(`{"level":"fatal"}`), &c)
	fmt.Println(err)
}

