	"uuid"
)

func main() {
	var ids []uuid.UUID
	for i := 0; i < 5; i++ {
		ids = append(ids, uuid.NewV7())
	}

	sorted := true
	for i := 1; i < len(ids); i++ {
		if ids[i-1].Compare(ids[i]) >= 0 {
			sorted = false
		}
	}
	fmt.Println("versiya:", ids[0][6]>>4)
	fmt.Println("o'sish tartibida:", sorted)

	byID := map[uuid.UUID]string{ids[0]: "birinchi"}
	fmt.Println(byID[ids[0]], len(byID))

	text, _ := ids[0].MarshalText()
	fmt.Println(len(text))
}
